// Package transport provides predefined transport protocol.
package transport

import "strings"

// Protocol indicates the transport protocol.
type Protocol int

// Predefined transport protocols.
const (
	PurePayload Protocol = 0

	// Basic protocol flags
	TTHeader Protocol = 1 << iota
	Framed
	HTTP
	GRPC
	HESSIAN2
	STREAMING

	// Composite protocols
	TTHeaderFramed Protocol = TTHeader | Framed

	// Dedicated streaming protocols
	TTHeaderStreaming Protocol = 64
	GRPCStreaming     Protocol = 128
)

// Unknown indicates the protocol is unknown.
const Unknown = "Unknown"

// String prints human readable information.
func (tp Protocol) String() string {
	// Handle special composite cases first
	switch tp {
	case PurePayload:
		return "PurePayload"
	case TTHeaderStreaming:
		return "TTHeaderStreaming"
	case GRPCStreaming:
		return "GRPCStreaming"
	}

	// Build composite string for bitwise combinations
	var parts []string
	if tp&TTHeader != 0 {
		parts = append(parts, "TTHeader")
	}
	if tp&Framed != 0 {
		parts = append(parts, "Framed")
	}
	if tp&HTTP != 0 {
		parts = append(parts, "HTTP")
	}
	if tp&GRPC != 0 {
		parts = append(parts, "GRPC")
	}
	if tp&HESSIAN2 != 0 {
		parts = append(parts, "HESSIAN2")
	}
	if tp&STREAMING != 0 {
		parts = append(parts, "STREAMING")
	}

	if len(parts) > 0 {
		return strings.Join(parts, "|")
	}
	return Unknown
